/* jacobi-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-2d.h"

/* --------------------------------------------------------------------
 * Tunable parameters
 * --------------------------------------------------------------------
 *
 * JACOBI_2D_BLOCK_J controls blocking in the inner (j) dimension.
 *  - Set to a positive value to enable blocking (default: 64).
 *  - Set to 0 to disable blocking and use a single contiguous j-loop.
 *
 * This does not change the numerical algorithm; it only changes
 * how the iteration space is traversed to improve cache locality
 * and to give the compiler better opportunities for vectorization.
 */
#ifndef JACOBI_2D_BLOCK_J
# define JACOBI_2D_BLOCK_J 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      /* Take row pointers once per outer iteration to avoid
         repeated 2D index arithmetic and improve cache behavior. */
      DATA_TYPE *restrict Ai = A[i];
      DATA_TYPE *restrict Bi = B[i];

      for (j = 0; j < n; j++)
	{
	  Ai[j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	  Bi[j] = ((DATA_TYPE) i*(j+3) + 3) / n;
	}
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* tsteps and n are kept for API compatibility; the PolyBench
     macros _PB_TSTEPS and _PB_N drive the actual loop bounds. */
  (void)tsteps;
  (void)n;

  /* Hoist the constant used in the stencil into a local variable so the
     compiler can keep it in a register and avoid recomputing it. */
  const DATA_TYPE c = SCALAR_VAL(0.2);

#pragma scop
  for (int t = 0; t < _PB_TSTEPS; t++)
    {
      /* ------------------------------------------------------------------
       * First sweep: update B from A
       * ------------------------------------------------------------------
       * Access pattern:
       *   - j is the innermost loop to keep accesses along rows contiguous.
       *   - Row pointers (Ai, Aim1, Aip1, Bi) avoid repeated 2D index
       *     arithmetic and help the compiler vectorize the inner loop.
       * ------------------------------------------------------------------ */
      for (int i = 1; i < _PB_N - 1; i++)
	{
	  DATA_TYPE       *restrict Bi   = B[i];
	  const DATA_TYPE *restrict Ai   = A[i];
	  const DATA_TYPE *restrict Aim1 = A[i-1];
	  const DATA_TYPE *restrict Aip1 = A[i+1];

#if JACOBI_2D_BLOCK_J > 0
	  /* Block the inner dimension to improve locality for large N.
	     Each block still processes j in increasing order, so the
	     numerical computation is unchanged. */
	  for (int jj = 1; jj < _PB_N - 1; jj += JACOBI_2D_BLOCK_J)
	    {
	      int j_end = jj + JACOBI_2D_BLOCK_J;
	      if (j_end > _PB_N - 1)
		j_end = _PB_N - 1;

	      /* Tell GCC there are no loop-carried dependencies in j,
	         enabling vectorization, and request some unrolling. */
#pragma GCC ivdep
#pragma GCC unroll 8
	      for (int j = jj; j < j_end; j++)
		{
		  Bi[j] = c * (Ai[j]     +
			       Ai[j-1]   +
			       Ai[j+1]   +
			       Aip1[j]   +
			       Aim1[j]);
		}
	    }
#else
	  /* No blocking: a single, fully contiguous inner loop. */
#pragma GCC ivdep
#pragma GCC unroll 8
	  for (int j = 1; j < _PB_N - 1; j++)
	    {
	      Bi[j] = c * (Ai[j]     +
			   Ai[j-1]   +
			   Ai[j+1]   +
			   Aip1[j]   +
			   Aim1[j]);
	    }
#endif
	}

      /* ------------------------------------------------------------------
       * Second sweep: update A from B
       * ------------------------------------------------------------------ */
      for (int i = 1; i < _PB_N - 1; i++)
	{
	  DATA_TYPE       *restrict Ai   = A[i];
	  const DATA_TYPE *restrict Bi   = B[i];
	  const DATA_TYPE *restrict Bim1 = B[i-1];
	  const DATA_TYPE *restrict Bip1 = B[i+1];

#if JACOBI_2D_BLOCK_J > 0
	  for (int jj = 1; jj < _PB_N - 1; jj += JACOBI_2D_BLOCK_J)
	    {
	      int j_end = jj + JACOBI_2D_BLOCK_J;
	      if (j_end > _PB_N - 1)
		j_end = _PB_N - 1;

#pragma GCC ivdep
#pragma GCC unroll 8
	      for (int j = jj; j < j_end; j++)
		{
		  Ai[j] = c * (Bi[j]     +
			       Bi[j-1]   +
			       Bi[j+1]   +
			       Bip1[j]   +
			       Bim1[j]);
		}
	    }
#else
#pragma GCC ivdep
#pragma GCC unroll 8
	  for (int j = 1; j < _PB_N - 1; j++)
	    {
	      Ai[j] = c * (Bi[j]     +
			   Bi[j-1]   +
			   Bi[j+1]   +
			   Bip1[j]   +
			   Bim1[j]);
	    }
#endif
	}
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
