 *
 * These control the tile sizes in the i- and j-dimensions.  They can
 * be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DJACOBI_2D_BLOCK_I=64 -DJACOBI_2D_BLOCK_J=64 ...
 *
