   - Use restrict-qualified local aliases for A and B to help alias analysis.
   - Hoist constant loop bounds and the stencil weight out of the loops.
   - Reduce address arithmetic by caching row pointers per i-iteration.
   - Preserve row-major, contiguous access in the innermost j loop to
     maximize vectorization and cache line utilization.
   - Optional spatial blocking in both i and j directions, controlled
     by JACOBI_2D_BLOCK_I / JACOBI_2D_BLOCK_J.
*/
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
