  const int T       = _PB_TSTEPS;
  const int Ni      = _PB_N;
  const int i_start = 1;
  const int i_end   = Ni - 1;  /* exclusive upper bound */
  const int j_start = 1;
  const int j_end   = Ni - 1;  /* exclusive upper bound */

  const DATA_TYPE w = SCALAR_VAL(0.2);

#pragma scop
  for (int t = 0; t < T; ++t)
    {
      /* ------------------------------------------------------------
       * Sweep 1: B = J(A)
       * ------------------------------------------------------------
       * Each (i,j) interior point of B is updated from the
       * 5-point stencil of A.  The computation for different
       * points is independent, so we can freely reorder the
       * traversal as long as we cover the full interior exactly once.
       *
       * We use simple rectangular blocking in (i,j) to improve
       * cache locality on large grids while keeping the innermost
       * loop over contiguous memory for good vectorization.
       * ------------------------------------------------------------ */
      for (int ii = i_start; ii < i_end; ii += JACOBI_2D_BLOCK_I)
        {
          const int i_max = (ii + JACOBI_2D_BLOCK_I < i_end) ? (ii + JACOBI_2D_BLOCK_I) : i_end;

          for (int jj = j_start; jj < j_end; jj += JACOBI_2D_BLOCK_J)
            {
              const int j_max = (jj + JACOBI_2D_BLOCK_J < j_end) ? (jj + JACOBI_2D_BLOCK_J) : j_end;

              for (int i = ii; i < i_max; ++i)
                {
