       * Sweep 2: A = J(B)
       * ------------------------------------------------------------
       * Same pattern as above, but with A and B swapped.  The whole
       * update depends only on the fully-updated B from this time
       * step, so this sweep must remain after the first sweep in t.
       * ------------------------------------------------------------ */
      for (int ii = i_start; ii < i_end; ii += JACOBI_2D_BLOCK_I)
