          for (int jj = j_start; jj < j_end; jj += JACOBI_2D_BLOCK_J)
            {
              const int j_max = (jj + JACOBI_2D_BLOCK_J < j_end) ? (jj + JACOBI_2D_BLOCK_J) : j_end;

              for (int i = ii; i < i_max; ++i)
                {
                  DATA_TYPE *restrict Ai   = A_[i];
                  DATA_TYPE *restrict Bi   = B_[i];
                  DATA_TYPE *restrict Bim1 = B_[i-1];
                  DATA_TYPE *restrict Bip1 = B_[i+1];

                  #pragma GCC ivdep
                  for (int j = jj; j < j_max; ++j)
                    {
                      Ai[j] = w * (Bi[j]   +
                                   Bi[j-1] +
                                   Bi[j+1] +
                                   Bip1[j] +
                                   Bim1[j]);
                    }
                }
            }
        }
